<template><div class="detail-shell"><AdminNav active="live" /><main><Link href="/admin/dashboard?tab=live" class="back">← Back to orders</Link><p class="eyebrow">Order #{{ order.id }}</p><h1>{{ order.product?.name || 'Produce order' }}</h1><p class="muted">{{ order.product?.user?.name }} → {{ order.buyer?.name }} · Driver: {{ order.driver?.name || 'Unassigned' }}</p><div class="grid"><section class="panel"><h2>Load evidence</h2><p v-if="order.verification">Claimed grade {{ order.verification.claimed_grade }} → verified grade {{ order.verification.actual_grade }}</p><p v-if="order.verification">Freshness: {{ order.verification.freshness_match ? 'Matches' : 'Does not match' }} · Packaging: {{ order.verification.packaging_ok ? 'OK' : 'Not OK' }}</p><div class="photos"><img v-for="photo in order.verification?.pickup_photos || []" :key="photo" :src="'/storage/' + photo" alt="Pickup evidence"><img v-if="order.delivery_photo_path" :src="'/storage/' + order.delivery_photo_path" alt="Delivery evidence"></div></section><section class="panel"><h2>Parties and money</h2><p>Farmer: {{ order.product?.user?.name }} · {{ order.product?.user?.phone_number }}</p><p>Buyer: {{ order.buyer?.name }} · {{ order.buyer?.phone_number }}</p><p>Driver: {{ order.driver?.name || 'Unassigned' }} · {{ order.driver?.phone_number || '—' }}</p><p>Escrow: {{ order.payment_status }} · GH₵ {{ Number(order.adjusted_price ?? order.total_price).toFixed(2) }}</p></section></div><section class="panel"><h2>Audit timeline</h2><div class="timeline"><div v-for="event in order.events" :key="event.id" class="event"><span class="dot"></span><div><strong>{{ event.event }}</strong><p>{{ event.actor?.name || event.actor_role || 'System' }} · {{ formatDate(event.created_at) }}</p></div></div></div></section></main></div></template>
